/// Server to client frames. A held socket never counts as activity and never keeps a computer awake.
public enum FeedMessage: Codable, Hashable, Sendable {
    case feedChanges(FeedChanges)
    case feedReset(FeedReset)
    case feedState(FeedState)
    case feedHeartbeat(FeedHeartbeat)

    private enum TagKey: String, CodingKey { case tag = "type" }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: TagKey.self)
        let tag = try c.decode(String.self, forKey: .tag)
        switch tag {
        case "changes": self = .feedChanges(try FeedChanges(from: decoder))
        case "reset": self = .feedReset(try FeedReset(from: decoder))
        case "state": self = .feedState(try FeedState(from: decoder))
        case "heartbeat": self = .feedHeartbeat(try FeedHeartbeat(from: decoder))
        default: throw DecodingError.dataCorruptedError(forKey: .tag, in: c, debugDescription: "unknown type \(tag)")
        }
    }

    public func encode(to encoder: Encoder) throws {
        var c = encoder.container(keyedBy: TagKey.self)
        switch self {
        case .feedChanges(let v): try c.encode("changes", forKey: .tag); try v.encode(to: encoder)
        case .feedReset(let v): try c.encode("reset", forKey: .tag); try v.encode(to: encoder)
        case .feedState(let v): try c.encode("state", forKey: .tag); try v.encode(to: encoder)
        case .feedHeartbeat(let v): try c.encode("heartbeat", forKey: .tag); try v.encode(to: encoder)
        }
    }
}

