    private enum TagKey: String, CodingKey { case tag = "type" }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: TagKey.self)
        let tag = try c.decode(String.self, forKey: .tag)
        switch tag {
        case "files.changed": self = .filesChanged(try FilesChanged(from: decoder))
        case "files.inbox.dropped": self = .inboxDropped(try InboxDropped(from: decoder))
        case "files.task.result": self = .taskResult(try TaskResult(from: decoder))
        case "files.share.accessed": self = .shareAccessed(try ShareAccessed(from: decoder))
        case "files.conflict": self = .conflictCreated(try ConflictCreated(from: decoder))
        default: throw DecodingError.dataCorruptedError(forKey: .tag, in: c, debugDescription: "unknown type \(tag)")
        }
    }

    public func encode(to encoder: Encoder) throws {
        var c = encoder.container(keyedBy: TagKey.self)
        switch self {
        case .filesChanged(let v): try c.encode("files.changed", forKey: .tag); try v.encode(to: encoder)
        case .inboxDropped(let v): try c.encode("files.inbox.dropped", forKey: .tag); try v.encode(to: encoder)
        case .taskResult(let v): try c.encode("files.task.result", forKey: .tag); try v.encode(to: encoder)
        case .shareAccessed(let v): try c.encode("files.share.accessed", forKey: .tag); try v.encode(to: encoder)
        case .conflictCreated(let v): try c.encode("files.conflict", forKey: .tag); try v.encode(to: encoder)
        }
    }
}

